#!/usr/bin/env python3
"""Exercise RFC 9934 PEM generated by either browntls or OpenSSL 4.0.3."""

import argparse
import base64
import binascii
import secrets
import struct
import sys
import time

import e2e

PEER = "openssl-ech"
INNER = "ech-inner.test"
PUBLIC = e2e.ECH_PUBLIC_NAME
PORT = e2e.PORT
MESSAGE = "hello from browntls"
KEMS = {"x25519": 0x20, "x448": 0x21, "p256": 0x10, "p384": 0x11, "p521": 0x12}
DOCKER_USER = "65532:65532"

# Only emit the public block after validating the entire file, then copy it to
# the client volume. Private fixtures never appear in client mounts or logs.
PUBLISH = """
awk '
    NR == 1 { if ($0 != "-----BEGIN ECHCONFIG-----") bad = 1; next }
    $0 == "-----END ECHCONFIG-----" && !ended { ended = 1; next }
    { if (ended || $0 !~ /^[A-Za-z0-9+\\/=]+$/) bad = 1; blob = blob $0 }
    END { if (bad || !ended || !length(blob)) exit 1; print blob }
' "$1"
cp "$1" "$2"
"""


def check_public_config(encoded, kem):
    try:
        config = base64.b64decode(encoded.strip(), validate=True)
        list_len, version, config_len, _, kem_id = struct.unpack_from("!HHHBH", config)
    except (binascii.Error, struct.error, ValueError) as error:
        raise RuntimeError("invalid public ECHConfigList") from error
    if version != 0xFE0D or list_len != len(config) - 2 or config_len != list_len - 4:
        raise RuntimeError("expected one RFC 9849 ECHConfig in the public PEM")
    if kem_id != KEMS[kem]:
        raise RuntimeError(f"expected {kem} in public ECHConfig, found KEM 0x{kem_id:04x}")


def check_browntls(output, role):
    rows = e2e.events(output)
    if any(row.get("event") in {"error", "ech-rejected", "ech-required"} for row in rows):
        raise RuntimeError(f"browntls {role} reported an error or rejected ECH")
    connections = [row for row in rows if row.get("event") == "connection"]
    sent, received = (MESSAGE, MESSAGE[::-1])
    if role == "server":
        sent, received = received, sent
    expected = {"role": role, "version": "TLSv1_3", "ech": "Accepted", "io": "async",
                "sent": sent, "received": received}
    if role == "server":
        expected["server_name"] = INNER
    else:
        expected["peer_certificates"] = 1
    if len(connections) != 1 or any(connections[0].get(k) != v for k, v in expected.items()):
        raise RuntimeError(f"browntls {role} did not report one accepted TLS 1.3 data exchange")


def commands(image, peer, fixture, role):
    private = f"/server/{fixture}/ech.pem"
    retry = f"/server/{fixture}/ech-public.pem"
    public = f"/client/{fixture}.pem"
    endpoint = f"{e2e.SERVER_ALIAS}:{PORT}"
    tls = ["--tls", "1.3", "--group", "X25519", "--async"]
    if role == "server":
        return (
            [image, "server", "--listen", f"0.0.0.0:{PORT}", "--accept", "1", *tls,
             "--cert", "/server/pki/inner.pem", "--key", "/server/pki/inner.key",
             "--sni-cert", f"{PUBLIC},/server/pki/public.pem,/server/pki/public.key",
             "--ech-pem", private, "--ech-retry-pem", retry],
            [peer, "openssl-ech", "client", endpoint, INNER, public, "/client/ca.pem"],
        )
    return (
        [peer, "openssl-ech", "server", f"0.0.0.0:{PORT}", INNER, private,
         "/server/pki/inner.pem", "/server/pki/inner.key"],
        [image, "client", "--connect", endpoint, "--server-name", INNER, *tls,
         "--ca", "/client/ca.pem", "--ech-pem", public,
         "--message", MESSAGE, "--expect-reply", MESSAGE[::-1]],
    )


def wait_listening(name, marker):
    deadline = time.monotonic() + 25
    while time.monotonic() < deadline:
        logs = e2e.docker("logs", name, timeout=10, check=False)
        if any(marker in line for line in logs.stdout.splitlines()):
            return
        if e2e.docker("inspect", "-f", "{{.State.Running}}", name,
                      timeout=10).stdout.strip() == "false":
            raise RuntimeError(f"server exited before listening: {logs.stderr.strip()}")
        time.sleep(0.2)
    raise RuntimeError("server did not report its listening socket")


def owned_resources(kind, label):
    columns = {"container": "{{.ID}} {{.Names}}", "volume": "{{.Name}} {{.Name}}",
               "network": "{{.ID}} {{.Name}}"}
    flags = {"container": ["--all", "--no-trunc"], "volume": [], "network": ["--no-trunc"]}
    output = e2e.docker(kind, "ls", *flags[kind], "--filter", f"label={label}",
                        "--format", columns[kind], timeout=20).stdout
    return dict(line.split(maxsplit=1) for line in output.splitlines() if line.strip())


def cleanup_run(run, label, volume_names):
    problems = []
    for kind, flags in (("container", ["-f"]), ("volume", []), ("network", [])):
        try:
            resources = owned_resources(kind, label)
        except (OSError, RuntimeError, ValueError) as error:
            names = ", ".join(volume_names) if kind == "volume" else run
            problems.append(f"cannot determine custody of Docker {kind} resources for {names}: {error}")
            continue
        deletion_errors = {}
        for identifier, name in resources.items():
            try:
                # Volume names are the only Docker handle for a volume. Renew
                # the label check before using one. Containers and networks
                # can be removed by their immutable IDs.
                if kind != "volume" or name in owned_resources(kind, label):
                    e2e.docker(kind, "rm", *flags, identifier, timeout=20)
            except (OSError, RuntimeError, ValueError) as error:
                deletion_errors[identifier] = str(error)
        try:
            remaining = owned_resources(kind, label)
        except (OSError, RuntimeError, ValueError) as error:
            names = ", ".join(resources.values()) or run
            problems.append(f"cannot verify removal of Docker {kind} resources for {names}: {error}")
            continue
        for identifier, name in remaining.items():
            detail = deletion_errors.get(identifier, "still present after removal")
            problems.append(f"Docker {kind} {name}: {detail}")
    return problems


def exchange(image, peer, run, network, label, fixture, role):
    server_cmd, client_cmd = commands(image, peer, fixture, role)
    name = f"{run}-{fixture}-{role}"
    flags = ["--label", label, "--network", network]
    server = name + "-server"
    client = name + "-client"
    try:
        server_id = e2e.docker(
            "run", "-d", "--name", server, *flags, "--network-alias", e2e.SERVER_ALIAS,
            "--mount", f"type=volume,src={run}-server,dst=/server,readonly",
            "--user", DOCKER_USER, *server_cmd, timeout=25,
        ).stdout.strip()
        marker = '"event":"listening"' if role == "server" else "listening"
        wait_listening(server_id, marker)
        result = e2e.docker("run", "--rm", "--name", client, *flags,
                            "--mount", f"type=volume,src={run}-client,dst=/client,readonly",
                            "--user", DOCKER_USER, *client_cmd, timeout=55)
        status = e2e.docker("wait", server_id, timeout=20).stdout.strip()
        logs = e2e.docker("logs", server_id, timeout=10)
        if status != "0":
            raise RuntimeError(f"server exited with status {status}: {logs.stderr.strip()}")
        if role == "server":
            check_browntls(logs.stdout, role)
            verified = "accepted TLSv1.3, server certificate and data verified"
            output = result.stdout
        else:
            check_browntls(result.stdout, role)
            verified = "accepted TLSv1.3, inner SNI and data verified"
            output = logs.stdout
        if output.splitlines().count(verified) != 1:
            raise RuntimeError("OpenSSL peer did not confirm ECH acceptance and data")
    except RuntimeError as error:
        raise RuntimeError(f"{fixture}, browntls {role}: {error}") from error


def run_cases(image, peer):
    run = f"browntls-ech-{secrets.token_hex(8)}"
    label = f"{e2e.LABEL}={secrets.token_hex(16)}"
    server_volume = f"{run}-server"
    client_volume = f"{run}-client"
    fixture_name = f"{run}-fixtures"
    server_mount = ["--mount", f"type=volume,src={server_volume},dst=/server"]
    client_mount = ["--mount", f"type=volume,src={client_volume},dst=/client"]
    fixture_args = ["run", "--rm", "--name", fixture_name, "--label", label, "--network", "none"]
    user = ["--user", DOCKER_USER]

    def shell(script, *args, root=False):
        return e2e.docker(*fixture_args, *server_mount, *client_mount,
                          *([] if root else user), "--entrypoint", "sh", peer,
                          "-ec", script, "fixtures", *args, timeout=45).stdout

    run_error = None
    try:
        network = e2e.docker("network", "create", "--label", label, run).stdout.strip()
        for volume in (server_volume, client_volume):
            e2e.docker("volume", "create", "--label", label, volume)
            # Docker can report success when a named volume already exists.
            if volume not in owned_resources("volume", label):
                raise RuntimeError(f"Docker volume {volume} lacks this run's ownership label")
        shell("mkdir /server/pki\n"
              f'sh {e2e.SHARE}/gen-ech-pki.sh /server/pki "$1" "$2"\n'
              "cp /server/pki/ca.pem /client/ca.pem\n"
              f"chown -R {DOCKER_USER} /server /client", INNER, PUBLIC, root=True)
        for kem in KEMS:
            for generator in ("openssl", "browntls"):
                fixture = f"{generator}-{kem}"
                directory = f"/server/{fixture}"
                if generator == "openssl":
                    shell('umask 077\nmkdir "$1"\n'
                          'openssl ech -public_name "$2" -suite "$3" '
                          '-out "$1/ech.pem"\n'
                          'openssl ech -in "$1/ech.pem" -out "$1/ech-public.pem"',
                          directory, PUBLIC, f"{KEMS[kem]:#x},0x1,0x1")
                else:
                    e2e.docker(*fixture_args, *server_mount, *user, image, "ech-keygen", "--out",
                               directory, "--public-name", PUBLIC, "--config-id", "7",
                               "--ech-pem", "--ech-kem", kem, timeout=45)
                encoded = shell(PUBLISH, f"{directory}/ech-public.pem", f"/client/{fixture}.pem")
                check_public_config(encoded, kem)
                for role in ("server", "client"):
                    exchange(image, peer, run, network, label, fixture, role)
                print(f"{fixture}: accepted and exchanged data with browntls in both roles",
                      flush=True)
    except BaseException as error:
        run_error = error
        raise
    finally:
        problems = cleanup_run(run, label, (server_volume, client_volume))
        if problems:
            message = "cleanup failed:\n" + "\n".join(problems)
            if run_error is None:
                raise RuntimeError(message)
            print(message, file=sys.stderr)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--image", required=True, help="built browntls-e2e image")
    parser.add_argument("--peer-image", default=e2e.peer_image_tag(PEER))
    parser.add_argument("--build-peer", action="store_true", help="build the pinned OpenSSL image")
    args = parser.parse_args()
    if args.build_peer and args.peer_image != e2e.peer_image_tag(PEER):
        parser.error("--build-peer builds the default --peer-image tag")
    try:
        if args.build_peer:
            e2e.build_peer_image(PEER)
        if not e2e.image_exists(args.image) or not e2e.image_exists(args.peer_image):
            raise RuntimeError("the browntls and OpenSSL 4.0.3 peer images must exist")
        run_cases(args.image, args.peer_image)
    except (OSError, RuntimeError) as error:
        print(f"Docker ECH PEM check failed: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
